"""ANALYSES.md: the catalogue of every analysis, generated from the registry.

Never edit ANALYSES.md by hand; `uv run bomstylo index` rewrites it (and the
test suite fails if it is out of date).
"""
from __future__ import annotations

from . import paths, results
from .analysis import registry

OUT = paths.ROOT / "ANALYSES.md"


def render() -> str:
    reg = registry()
    srcs = {s["id"]: s for s in results.manifest()["sources"]}
    fams = sorted({a.family for a in reg.values()})
    lines = ["# Analyses", "",
             "Generated by `uv run bomstylo index` from each analysis's `ANALYSIS` declaration. "
             "Don't edit by hand.", "",
             "Each row is one module under `analyses/<family>/`. *Label* is `registered` (run exactly as a "
             "pre-registration fixed it) or `exploratory`. *Status* is whether the committed result matches "
             "the current inputs (`uv run bomstylo status`). The Requiem record holds the headline numbers; "
             "`requiem get <record>` reports `stale: true` when an input has changed.", ""]
    for fam in fams:
        lines += [f"## {fam}", "", "| id | label | question | reads | depends on | status | Requiem record |",
                  "|---|---|---|---|---|---|---|"]
        for a in (x for x in reg.values() if x.family == fam):
            st = results.status(a)[0]
            reads = ", ".join(a.corpora + [f"annotations/{n}" for n in a.annotations]
                              + ([f"preregistrations/{a.preregistration}"] if a.preregistration else []))
            src = a.source_path.relative_to(paths.ROOT).as_posix()
            lines.append(f"| [`{a.id}`]({src}) | {a.label} | {a.question} | {reads} | "
                         f"{', '.join(a.depends) or '—'} | {st} | `{a.requiem_id}` |")
        lines.append("")
    lines += ["## Sources", "", "| id | title | read by |", "|---|---|---|"]
    for sid, s in srcs.items():
        users = [a.id for a in reg.values() if sid in a.corpora]
        lines.append(f"| `{sid}` | {s['title']} | {', '.join(users) or '—'} |")
    return "\n".join(lines) + "\n"


def write() -> str:
    OUT.write_text(render(), encoding="utf-8")
    return str(OUT.relative_to(paths.ROOT))
